def head(title, description):
    return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#faf9f6"><meta name="description" content="{html.escape(description, quote=True)}"><title>{html.escape(title)} — Product Thinking</title><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/styles.css"><script src="assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="wrap"><header class="site-nav"><a class="brand" href="index.html" aria-label="Product Thinking home"><img class="brand-mark" src="assets/icon.svg" alt=""><span>product <em>/</em> thinking</span></a><nav class="nav-links" aria-label="Main navigation"><a href="index.html#work">Case studies</a><a href="index.html#approach">My approach</a><a class="nav-cta" href="full-study.html">Full written studies <span class="arrow" aria-hidden="true">↗</span></a></nav></header>'''

def footer():
    return '''<footer class="footer"><div class="footer-left"><a class="footer-name" href="index.html">product / thinking</a><span>Independent concept portfolio</span></div><div class="footer-right"><a href="full-study.html">Full written studies ↗</a><a href="#main">Back to top ↑</a></div></footer></div></body></html>'''

def section(key, number, title, content):
    return f'<section class="case-section" id="{key}"><div class="eyebrow">{number} / {key.replace("-", " ")}</div><h2>{title}</h2>{content}</section>'

def table(headers, rows):
    body = ''.join('<tr>' + ''.join(f'<th scope="row">{cell}</th>' if i == 0 else f'<td>{cell}</td>' for i, cell in enumerate(row)) + '</tr>' for row in rows)
    return '<div class="table-scroll"><table><thead><tr>' + ''.join(f'<th scope="col">{h}</th>' for h in headers) + '</tr></thead><tbody>' + body + '</tbody></table></div>'

def experiment(kind, title, tabs, rows, default_values):
    names = ['Baseline', 'Hybrid v1', 'Hybrid v2'] if kind == 'relevance' else ['Baseline', 'Unified v1', 'Unified v2']
    metric_buttons = ''.join(f'<button class="metric-tab" type="button" data-metric="{key}" aria-pressed="{str(i == 0).lower()}">{label}</button>' for i, (key, label) in enumerate(tabs))
    chart_rows = ''.join(f'<div class="chart-row" data-chart-row><span class="chart-row-label">{name}<small>{["Reference","First attempt","Iteration"][i]}</small></span><div class="chart-track" aria-hidden="true"><div class="chart-bar" data-bar style="width:{width}%"></div><span class="chart-gate" data-gate hidden></span></div><span class="chart-value" data-value>{value}</span></div>' for i,(name,(width,value)) in enumerate(zip(names,default_values)))
    return f'''<div class="experiment" data-experiment="{kind}"><div class="experiment-header"><div><h3>{title}</h3><p>Compare the baseline, the failed attempt, and the iteration.</p></div><span class="simulation-tag">Simulated data</span></div><div class="metric-tabs" role="group" aria-label="Select an experiment metric">{metric_buttons}</div><div class="chart"><div class="chart-context"><span data-chart-label>{'Semantic NDCG@10' if kind == 'relevance' else 'Required-source coverage'}</span><span class="direction" data-chart-direction>Higher is better</span></div><div class="chart-rows">{chart_rows}</div><div class="chart-axis" aria-hidden="true"><span data-axis-start>0</span><span data-axis-end>{'1.00' if kind == 'relevance' else '100%'}</span></div><p class="sr-only" data-chart-summary role="status" aria-live="polite" aria-atomic="true">All experiment values are simulated. The full metric table is available below.</p></div><p class="chart-insight" data-chart-insight>{'v1 improves semantic relevance but fails exact-match, latency, and cost gates. v2 warrants further validation.' if kind == 'relevance' else 'Coverage alone does not justify launch. v1 fails the permission gate; v2 still requires independent validation.'}</p><details class="chart-table"><summary>View all simulated metrics</summary>{table(['Metric','Baseline','v1','v2'],rows)}</details></div><p class="fine-print">The bars start at zero. Dashed lines, when shown, mark the study’s assumed gate. These are illustrative benchmark results, not measured product outcomes. Passing a synthetic gate does not justify a production launch.</p>'''

def source_links(anchor):
    return f'<div class="source-action"><a href="full-study.html#{anchor}">Read the complete written study ↗</a></div>'

def case_page(title, subtitle, number, category, tags, sections, next_title, next_file, green=False):
    toc = ''.join(f'<a href="#{key}">{label}</a>' for key,label,_ in sections)
    body = ''.join(content for _,_,content in sections)
    return head(title, subtitle + ' Independent hypothetical case study; all metrics and results are simulated.') + f'''<main id="main"><div class="case-hero"><a class="back-link" href="index.html#work">← Back to the case studies</a><div class="eyebrow">Case study {number} / {category}</div><h1>{title}</h1><p class="subtitle">{subtitle}</p><div class="tags">{''.join(f'<span class="tag">{tag}</span>' for tag in tags)}</div><div class="disclosure-box"><strong>Independent, hypothetical case study.</strong> Every scenario, dataset, result, timeline, and team constraint is assumed or simulated. This is not a Clio project and does not represent access to its customers, telemetry, architecture, staff, or plans. It demonstrates decisions I would test, not work shipped or outcomes achieved.</div></div><div class="case-layout"><aside class="case-toc" aria-label="On this page"><span class="micro-label">Inside this study</span>{toc}</aside><div>{body}<a class="study-next {'green' if green else ''}" href="{next_file}"><div><span class="micro-label">Explore the other study</span><h3>{next_title}</h3></div><span class="arrow" aria-hidden="true">↗</span></a></div></div></main>''' + footer()

